This is the "sum of the nth row of consecutive odd numbers" pattern. The nth row starts at `n² - n + 1` and has `n` elements, and the sum is simply `n³`.

```javascript
function sumOfNthRow(start, n) {
  // nth row starts at start + (n*(n-1)) and has n elements
  const first = start + n * (n - 1);
  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += first + 2 * i;
  }
  return sum;
}
```

For the standard triangle (start = 1), this always equals `n³`:

```javascript
sumOfNthRow(1, 1); // 1
sumOfNthRow(1, 2); // 8   (3 + 5)
sumOfNthRow(1, 3); // 27  (7 + 9 + 11)
```

If you only ever need the standard triangle, you can skip the loop entirely: `return n ** 3;`.

Here's a p5.js sketch:

```javascript
let x, y;
let speed = 2;

function setup() {
  createCanvas(400, 400);
  x = width / 2;
  y = 0;
}

function draw() {
  background(20, 30, 50);

  // draw the snowflake
  stroke(255);
  strokeWeight(2);
  let r = 12;
  for (let i = 0; i < 6; i++) {
    let angle = i * PI / 3;
    let ex = x + cos(angle) * r;
    let ey = y + sin(angle) * r;
    line(x, y, ex, ey);
    // small branches
    let bx = x + cos(angle) * r * 0.6;
    let by = y + sin(angle) * r * 0.6;
    line(bx, by, bx + cos(angle + 0.6) * 6, by + sin(angle + 0.6) * 6);
    line(bx, by, bx + cos(angle - 0.6) * 6, by + sin(angle - 0.6) * 6);
  }

  // move down
  y += speed;

  // wrap to top when off the bottom
  if (y > height + r) {
    y = -r;
  }
}
```

The snowflake is drawn as six spokes with small branches. `y` increases each frame; once it passes the bottom edge (plus its radius), it resets to just above the top. Adjust `speed` for faster or slower falling.

