I can't write a full C compiler in a single reply — a real one is tens of thousands of lines. But I can give you a small, working compiler for a useful subset of C, one that compiles to x86-64 assembly and links against libc. Here's a complete, self-contained version in Python.

```python
#!/usr/bin/env python3
"""tinyc: compiles a subset of C to x86-64 Linux assembly."""
import re, sys

# --- Lexer ---
TOKEN = re.compile(r'''
    (?P<num>\d+) | (?P<id>[A-Za-z_]\w*) |
    (?P<op>==|!=|<=|>=|[-+*/(){};,=<>]) |
    (?P<ws>\s+) | (?P<bad>.)
''', re.X)

def lex(src):
    toks, i = [], 0
    while i < len(src):
        m = TOKEN.match(src, i)
        i = m.end()
        if m.lastgroup in ('ws',): continue
        if m.lastgroup == 'bad': raise SyntaxError(f"bad char {m.group()!r}")
        toks.append((m.lastgroup, m.group()))
    toks.append(('eof', ''))
    return toks

# --- Parser (recursive descent) ---
class P:
    def __init__(self, toks): self.t, self.i = toks, 0
    def peek(self): return self.t[self.i]
    def next(self): self.i += 1; return self.t[self.i-1]
    def expect(self, v):
        if self.peek()[1] != v: raise SyntaxError(f"expected {v!r}, got {self.peek()[1]!r}")
        return self.next()

    def program(self):
        funcs = []
        while self.peek()[1] != '': funcs.append(self.func())
        return funcs

    def func(self):
        self.expect('int'); name = self.next()[1]
        self.expect('('); self.expect(')')
        body = self.block()
        return (name, body)

    def block(self):
        self.expect('{'); stmts = []
        while self.peek()[1] != '}': stmts.append(self.stmt())
        self.expect('}'); return stmts

    def stmt(self):
        if self.peek()[1] == 'return':
            self.next(); e = self.expr(); self.expect(';'); return ('return', e)
        if self.peek()[1] == 'int':
            self.next(); name = self.next()[1]; self.expect('='); e = self.expr()
            self.expect(';'); return ('decl', name, e)
        if self.peek()[1] == 'if':
            self.next(); self.expect('('); c = self.expr(); self.expect(')')
            then = self.block()
            els = self.block() if self.peek()[1] == 'else' and not self.next() else None
            return ('if', c, then, els)
        if self.peek()[1] == 'while':
            self.next(); self.expect('('); c = self.expr(); self.expect(')')
            return ('while', c, self.block())
        if self.peek()[1] == '{': return ('block', self.block())
        e = self.expr(); self.expect(';'); return ('expr', e)

    def expr(self): return self.binary(0)
    BIN = [['==','!='], ['<','<=','>','>='], ['+','-'], ['*','/']]
    def binary(self, lvl):
        if lvl >= len(self.BIN): return self.unary()
        left = self.binary(lvl+1)
        while self.peek()[1] in self.BIN[lvl]:
            op = self.next()[1]; right = self.binary(lvl+1)
            left = ('bin', op, left, right)
        return left
    def unary(self):
        if self.peek()[1] in ('-','!'):
            op = self.next()[1]; return ('un', op, self.unary())
        return self.primary()
    def primary(self):
        kind, val = self.peek()
        if val == '(':
            self.next(); e = self.expr(); self.expect(')'); return e
        if kind == 'num': self.next(); return ('num', int(val))
        if kind == 'id':
            self.next()
            if self.peek()[1] == '(':
                self.next(); args = []
                if self.peek()[1] != ')':
                    args.append(self.expr())
                    while self.peek()[1] == ',': self.next(); args.append(self.expr())
                self.expect(')'); return ('call', val, args)
            return ('var', val)
        raise SyntaxError(f"unexpected {val!r}")

# --- Codegen ---
class Gen:
    def __init__(self): self.out = [];

Here's a React Native function using `react-native-ble-plx`, the standard library for BLE scanning. It scans while the app is in the foreground and stops automatically when the app goes to the background.

```javascript
import { BleManager } from 'react-native-ble-plx';
import { AppState } from 'react-native';

const manager = new BleManager();

export function scanForDevices(onDevice, { timeoutMs = 15000 } = {}) {
  let subscription = null;

  const start = () => {
    manager.startDeviceScan(null, null, (error, device) => {
      if (error) {
        console.warn('BLE scan error:', error.message);
        return;
      }
      if (device) onDevice(device);
    });
  };

  const stop = () => {
    manager.stopDeviceScan();
    if (subscription) subscription.remove();
  };

  // "Idle" = app is active but not in the background.
  subscription = AppState.addEventListener('change', (state) => {
    if (state === 'active') start();
    else stop();
  });

  if (AppState.currentState === 'active') start();

  const timer = setTimeout(stop, timeoutMs);

  // Call this to end scanning early.
  return () => {
    clearTimeout(timer);
    stop();
  };
}
```

A few things worth knowing:

- **Permissions.** On Android you need `BLUETOOTH_SCAN` and `BLUETOOTH_CONNECT` (API 31+), plus location permission on older versions. On iOS, add `NSBluetoothAlwaysUsageDescription` to Info.plist.
- **Background scanning** isn't really possible on iOS without special entitlements, and Android restricts it heavily. This scans only while the app is active.
- **Battery.** Continuous scanning drains battery fast. The `timeoutMs` default of 15s limits that; tune it to your needs.
- **Filtering.** Pass a service UUID as the first argument to `startDeviceScan` to cut noise and save power.

